// ============================================================
// Detectar Intención
// ------------------------------------------------------------
// Valida payload, sanea firebase_uid, calcula intent y guarda
// `startTime` para medir el tiempo total end-to-end.
// ============================================================

const payload = $json.body;
if (!payload) {
  throw new Error('Request body is missing');
}

const { userId, conversationId, messageId, userMessage, baseUrl } = payload;

if (!userId || typeof userId !== 'string') {
  throw new Error('userId is missing or not a string');
}
if (!conversationId || typeof conversationId !== 'string') {
  throw new Error('conversationId is missing or not a string');
}
if (!messageId || typeof messageId !== 'string') {
  throw new Error('messageId is missing or not a string');
}
if (!userMessage || typeof userMessage !== 'string') {
  throw new Error('userMessage is missing or not a string');
}

// Firebase UIDs son alfanuméricos (~28 chars). Rechazamos cualquier cosa
// fuera de patrón para evitar SQL injection al interpolarlos en el prompt.
if (!/^[A-Za-z0-9]{20,64}$/.test(userId)) {
  throw new Error(`userId does not match expected firebase_uid pattern: ${userId}`);
}

// Normaliza texto (minúsculas + sin diacríticos) para matching robusto.
const normalized = userMessage
  .toLowerCase()
  .normalize('NFD')
  .replace(/\p{Diacritic}/gu, '');

const bookKeywords = [
  // ES
  'libro', 'libros', 'recomienda', 'recomendacion', 'recomendaciones',
  'recomendar', 'leer', 'lectura', 'lecturas', 'autor', 'autora',
  'novela', 'novelas', 'cuento', 'cuentos', 'ficcion', 'no ficcion',
  'fantasia', 'romance', 'misterio', 'thriller', 'suspense', 'terror',
  'ciencia ficcion', 'manga', 'comic', 'clasico', 'clasicos',
  'biografia', 'ensayo', 'poesia', 'saga', 'bestseller', 'bestsellers',
  'genero', 'generos', 'sugiere', 'sugerencia', 'biblioteca', 'libreria',
  // EN
  'book', 'books', 'recommend', 'recommendation', 'recommendations',
  'suggest', 'reading', 'read', 'author', 'novel', 'fantasy', 'mystery',
  'sci-fi', 'sci fi', 'science fiction', 'romance novel', 'biography'
];

const casualKeywords = [
  // ES
  'hola', 'hey', 'buenos dias', 'buenas tardes', 'buenas noches',
  'que tal', 'como estas', 'como va', 'gracias', 'adios', 'hasta luego',
  'saludos', 'genial', 'perfecto',
  // EN
  'hi', 'hello', 'good morning', 'good afternoon', 'good evening',
  'how are you', 'thanks', 'thank you', 'bye', 'goodbye'
];

const bookMatches = bookKeywords.filter((k) => normalized.includes(k)).length;
const casualMatches = casualKeywords.filter((k) => normalized.includes(k)).length;

let intentType = 'out_of_scope';
let intentConfidence = 0;

if (bookMatches > 0 && bookMatches >= casualMatches) {
  intentType = 'book_recommendation';
  intentConfidence = Math.min(1, bookMatches / 4);
} else if (casualMatches > 0) {
  intentType = 'casual_chat';
  intentConfidence = 0.8;
} else if (normalized.length <= 12 && /[?¿!¡]/.test(userMessage)) {
  // Mensajes muy cortos con signo de pregunta/exclamación → probablemente casual.
  intentType = 'casual_chat';
  intentConfidence = 0.5;
}

return {
  userId,
  conversationId,
  messageId,
  userMessage,
  baseUrl: baseUrl || 'http://localhost:4200',
  intentType,
  intentConfidence: Number(intentConfidence.toFixed(2)),
  startTime: Date.now()
};

// ============================================================
// Normalizar Contexto
// ------------------------------------------------------------
// Convierte la respuesta de Firestore en un array plano
// {role, content} y lo fusiona con los datos de Detectar Intención.
// ============================================================

const firestoreData = $input.item.json;
const intent = $('Detectar Intención').item.json;

if (!intent?.userId) {
  throw new Error(`Missing intent data. Keys: ${Object.keys(intent || {}).join(', ')}`);
}

const rawDocs = firestoreData.documents || [];
const conversationContext = rawDocs
  .reverse()
  .map((doc) => ({
    role: doc?.fields?.role?.stringValue ?? null,
    content: doc?.fields?.content?.stringValue ?? ''
  }))
  .filter((msg) => msg.role === 'user' || msg.role === 'assistant');

return {
  ...intent,
  conversationContext
};

