={{ (() => {

// Helper: arrayValue para strings.
const toFirestoreStringArray = (arr) => ({
  values: (arr || []).map((v) => ({ stringValue: String(v) }))
});

// Helper: arrayValue para enteros (Firestore REST acepta integerValue como string).
const toFirestoreIntArray = (arr) => ({
  values: (arr || [])
    .map((v) => (typeof v === 'number' ? v : Number(v)))
    .filter((n) => Number.isFinite(n))
    .map((n) => ({ integerValue: String(Math.trunc(n)) }))
});

const recommendations = $json.metadata?.recommendations || [];
const processingTime = Number($json.metadata?.processingTime) || 0;
const intentConfidence = Number($json.metadata?.intentConfidence);

const metadataFields = {
  thoughts: { arrayValue: toFirestoreStringArray($json.metadata?.thoughts) },
  recommendations: { arrayValue: toFirestoreIntArray(recommendations) },
  recommendationsCount: { integerValue: String(recommendations.length) },
  used_querys: { arrayValue: toFirestoreStringArray($json.metadata?.used_querys) },
  intentType: { stringValue: $json.metadata?.intentType || 'unknown' },
  processingTime: { integerValue: String(Math.trunc(processingTime)) }
};

if (Number.isFinite(intentConfidence)) {
  metadataFields.intentConfidence = { doubleValue: intentConfidence };
}

return {
  fields: {
    content: { stringValue: $json.content || '' },
    status: { stringValue: 'completed' },
    metadata: { mapValue: { fields: metadataFields } }
  }
};

})() }}

