// ============================================================
// Preparar Error
// ------------------------------------------------------------
// Extrae userId/conversationId/messageId del nodo de origen
// (Webhook o Detectar Intención) para poder escribir el error
// en el mensaje correcto de Firestore.
// ============================================================

const errorData = $input.item.json;
const errorMessage = errorData?.error?.message || errorData?.message || 'Error desconocido';

let userId = null;
let conversationId = null;
let messageId = null;

try {
  const webhookData = $('Webhook').item.json;
  if (webhookData?.body) {
    userId = webhookData.body.userId;
    conversationId = webhookData.body.conversationId;
    messageId = webhookData.body.messageId;
  }
} catch (_) {}

try {
  const detectData = $('Detectar Intención').item.json;
  if (detectData) {
    userId = userId || detectData.userId;
    conversationId = conversationId || detectData.conversationId;
    messageId = messageId || detectData.messageId;
  }
} catch (_) {}

if (!userId || !conversationId || !messageId) {
  console.log('[n8n] Error handler: faltan identificadores para escribir en Firestore', {
    userId, conversationId, messageId, errorMessage
  });
}

return {
  userId: userId || '',
  conversationId: conversationId || '',
  messageId: messageId || '',
  errorContent: `Lo siento, ocurrió un error: ${errorMessage}. Por favor, intenta de nuevo.`
};
